import{_ as e,c as i,o,ag as s}from"./chunks/framework.DfL_BkQ-.js";const m=JSON.parse('{"title":"Solución de problemas","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/troubleshooting.md","filePath":"es/guide/troubleshooting.md","lastUpdated":1794112334000}'),l={name:"es/guide/troubleshooting.md"};function n(r,a,t,c,d,p){return o(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="solucion-de-problemas" tabindex="-1">Solución de problemas <a class="header-anchor" href="#solucion-de-problemas" aria-label="Permalink to &quot;Solución de problemas&quot;">​</a></h1><h2 id="problemas-habituales" tabindex="-1">Problemas habituales <a class="header-anchor" href="#problemas-habituales" aria-label="Permalink to &quot;Problemas habituales&quot;">​</a></h2><h3 id="la-aplicacion-no-se-inicia" tabindex="-1">La aplicación no se inicia <a class="header-anchor" href="#la-aplicacion-no-se-inicia" aria-label="Permalink to &quot;La aplicación no se inicia&quot;">​</a></h3><p><strong>Síntomas</strong>: Nicasa no arranca o se cierra de inmediato</p><p><strong>Soluciones</strong>:</p><ol><li>Asegúrate de usar macOS 10.13 o posterior</li><li>Comprueba que tienes al menos 4 GB de RAM</li><li>Reinicia tu Mac</li><li>Reinstala Nicasa desde el Mac App Store</li><li>Comprueba si hay aplicaciones en conflicto</li></ol><h3 id="las-capturas-de-pantalla-no-funcionan" tabindex="-1">Las capturas de pantalla no funcionan <a class="header-anchor" href="#las-capturas-de-pantalla-no-funcionan" aria-label="Permalink to &quot;Las capturas de pantalla no funcionan&quot;">​</a></h3><p><strong>Síntomas</strong>: la función de captura no funciona</p><p><strong>Soluciones</strong>:</p><ol><li><strong>Concede el permiso de grabación de pantalla</strong>: <ul><li>Ve a Ajustes del Sistema &gt; Privacidad y seguridad &gt; Grabación de pantalla</li><li>Marca la casilla junto a Nicasa</li><li>Reinicia Nicasa</li></ul></li><li>Asegúrate de que no haya otras herramientas de captura en ejecución</li><li>Prueba a reiniciar tu Mac</li></ol><h3 id="la-extension-de-chrome-no-funciona" tabindex="-1">La extensión de Chrome no funciona <a class="header-anchor" href="#la-extension-de-chrome-no-funciona" aria-label="Permalink to &quot;La extensión de Chrome no funciona&quot;">​</a></h3><p><strong>Síntomas</strong>: la extensión no aparece o no extrae imágenes</p><p><strong>Soluciones</strong>:</p><ol><li>Asegúrate de que la extensión está activada en Chrome</li><li>Comprueba que usas una versión compatible de Chrome</li><li>Prueba a actualizar la página web</li><li>Reinstala la extensión</li><li>Borra la caché y las cookies del navegador</li></ol><h3 id="las-imagenes-no-se-cargan" tabindex="-1">Las imágenes no se cargan <a class="header-anchor" href="#las-imagenes-no-se-cargan" aria-label="Permalink to &quot;Las imágenes no se cargan&quot;">​</a></h3><p><strong>Síntomas</strong>: no aparecen las miniaturas o las imágenes no se abren</p><p><strong>Soluciones</strong>:</p><ol><li>Comprueba los permisos de los archivos de imagen</li><li>Asegúrate de que las imágenes no estén dañadas</li><li>Verifica que el formato sea compatible (JPEG, PNG, GIF, BMP, TIFF, WebP)</li><li>Prueba a abrir la carpeta de nuevo</li><li>Reinicia Nicasa</li></ol><h3 id="rendimiento-lento" tabindex="-1">Rendimiento lento <a class="header-anchor" href="#rendimiento-lento" aria-label="Permalink to &quot;Rendimiento lento&quot;">​</a></h3><p><strong>Síntomas</strong>: la aplicación va lenta o las miniaturas tardan en cargar</p><p><strong>Soluciones</strong>:</p><ol><li>Cierra otras aplicaciones que consuman mucha memoria</li><li>Asegúrate de tener RAM libre suficiente (8 GB recomendados)</li><li>Reduce el tamaño de la cuadrícula de miniaturas en las preferencias</li><li>Limpia la caché de la aplicación</li><li>Reinicia tu Mac</li></ol><h3 id="el-editor-de-ia-no-funciona" tabindex="-1">El editor de IA no funciona <a class="header-anchor" href="#el-editor-de-ia-no-funciona" aria-label="Permalink to &quot;El editor de IA no funciona&quot;">​</a></h3><p><strong>Síntomas</strong>: las herramientas de edición con IA no están disponibles o no funcionan</p><p><strong>Soluciones</strong>:</p><ol><li>Asegúrate de tener una conexión a internet estable (para algunas funciones)</li><li>Comprueba que tu Mac cumple los requisitos mínimos</li><li>Reinicia Nicasa</li><li>Actualiza a la última versión</li><li>Contacta con el soporte si el problema persiste</li></ol><h3 id="problemas-de-permisos" tabindex="-1">Problemas de permisos <a class="header-anchor" href="#problemas-de-permisos" aria-label="Permalink to &quot;Problemas de permisos&quot;">​</a></h3><p><strong>Síntomas</strong>: la app solicita permisos o algunas funciones no funcionan</p><p><strong>Soluciones</strong>:</p><ol><li><strong>Grabación de pantalla</strong>: Ajustes del Sistema &gt; Privacidad y seguridad &gt; Grabación de pantalla</li><li><strong>Accesibilidad</strong>: Ajustes del Sistema &gt; Privacidad y seguridad &gt; Accesibilidad (para el modo superposición)</li><li><strong>Archivos y carpetas</strong>: Ajustes del Sistema &gt; Privacidad y seguridad &gt; Archivos y carpetas</li><li>Reinicia Nicasa después de conceder los permisos</li></ol><h3 id="problemas-con-el-modo-superposicion" tabindex="-1">Problemas con el modo superposición <a class="header-anchor" href="#problemas-con-el-modo-superposicion" aria-label="Permalink to &quot;Problemas con el modo superposición&quot;">​</a></h3><p><strong>Síntomas</strong>: el modo superposición transparente no funciona correctamente</p><p><strong>Soluciones</strong>:</p><ol><li>Concede el permiso de accesibilidad en Ajustes del Sistema</li><li>Asegúrate de que no haya otras herramientas de superposición en ejecución</li><li>Prueba a desactivar y volver a activar el modo superposición</li><li>Reinicia Nicasa</li></ol><h2 id="mensajes-de-error" tabindex="-1">Mensajes de error <a class="header-anchor" href="#mensajes-de-error" aria-label="Permalink to &quot;Mensajes de error&quot;">​</a></h2><h3 id="«se-requiere-permiso-de-grabacion-de-pantalla»" tabindex="-1">«Se requiere permiso de grabación de pantalla» <a class="header-anchor" href="#«se-requiere-permiso-de-grabacion-de-pantalla»" aria-label="Permalink to &quot;«Se requiere permiso de grabación de pantalla»&quot;">​</a></h3><p><strong>Solución</strong>: concede el permiso de grabación de pantalla como se describe arriba, en la sección «Las capturas de pantalla no funcionan».</p><h3 id="«no-se-pudo-cargar-la-imagen»" tabindex="-1">«No se pudo cargar la imagen» <a class="header-anchor" href="#«no-se-pudo-cargar-la-imagen»" aria-label="Permalink to &quot;«No se pudo cargar la imagen»&quot;">​</a></h3><p><strong>Posibles causas</strong>:</p><ul><li>El archivo está dañado</li><li>Formato no compatible</li><li>Problema de permisos del archivo</li><li>El archivo es demasiado grande</li></ul><p><strong>Soluciones</strong>:</p><ol><li>Prueba a abrir el archivo con Vista Previa para comprobar que es válido</li><li>Convierte el archivo a un formato compatible</li><li>Comprueba los permisos del archivo</li><li>Asegúrate de que el tamaño del archivo sea razonable</li></ol><h3 id="«la-extension-no-responde»" tabindex="-1">«La extensión no responde» <a class="header-anchor" href="#«la-extension-no-responde»" aria-label="Permalink to &quot;«La extensión no responde»&quot;">​</a></h3><p><strong>Solución</strong>: actualiza la página web y vuelve a intentarlo. Si persiste, reinstala la extensión.</p><h2 id="obtener-ayuda" tabindex="-1">Obtener ayuda <a class="header-anchor" href="#obtener-ayuda" aria-label="Permalink to &quot;Obtener ayuda&quot;">​</a></h2><p>Si sigues teniendo problemas:</p><ol><li>Consulta esta guía de solución de problemas</li><li>Visita nuestras <a href="/es/guide/faq.html">preguntas frecuentes</a></li><li>Envía una incidencia en <a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">GitHub</a></li><li>Incluye tu versión de macOS, la versión de Nicasa y los pasos detallados para reproducir el problema</li></ol><h2 id="informacion-del-sistema" tabindex="-1">Información del sistema <a class="header-anchor" href="#informacion-del-sistema" aria-label="Permalink to &quot;Información del sistema&quot;">​</a></h2><p>Al informar de problemas, incluye:</p><ul><li>Versión de macOS (menú Apple &gt; Acerca de este Mac)</li><li>Versión de Nicasa (Nicasa &gt; Acerca de Nicasa)</li><li>Modelo y chip del Mac (Apple Silicon o Intel)</li><li>Pasos para reproducir el problema</li><li>Cualquier mensaje de error</li></ul><p>Normalmente esto significa que el archivo de imagen se ha movido o eliminado. Prueba a reabrir la carpeta o a seleccionar otro directorio.</p><h3 id="«formato-no-compatible»" tabindex="-1">«Formato no compatible» <a class="header-anchor" href="#«formato-no-compatible»" aria-label="Permalink to &quot;«Formato no compatible»&quot;">​</a></h3><p>No se reconoce el formato de la imagen. Consulta nuestra lista de <a href="/es/guide/usage.html">formatos compatibles</a> o convierte la imagen a un formato compatible.</p><h3 id="«memoria-insuficiente»" tabindex="-1">«Memoria insuficiente» <a class="header-anchor" href="#«memoria-insuficiente»" aria-label="Permalink to &quot;«Memoria insuficiente»&quot;">​</a></h3><p>Tu sistema no tiene suficiente RAM. Cierra otras aplicaciones o amplía la memoria.</p><h2 id="solucion-de-problemas-avanzada" tabindex="-1">Solución de problemas avanzada <a class="header-anchor" href="#solucion-de-problemas-avanzada" aria-label="Permalink to &quot;Solución de problemas avanzada&quot;">​</a></h2><h3 id="ver-registros" tabindex="-1">Ver registros <a class="header-anchor" href="#ver-registros" aria-label="Permalink to &quot;Ver registros&quot;">​</a></h3><p>Para acceder a los registros de la aplicación:</p><ol><li>Ve a Ayuda &gt; Mostrar registros</li><li>O busca los registros en: <ul><li>Windows: <code>%APPDATA%\\Nicasa\\logs</code></li><li>macOS: <code>~/Library/Application Support/Nicasa/logs</code></li><li>Linux: <code>~/.config/Nicasa/logs</code></li></ul></li></ol><h3 id="restablecer-la-aplicacion" tabindex="-1">Restablecer la aplicación <a class="header-anchor" href="#restablecer-la-aplicacion" aria-label="Permalink to &quot;Restablecer la aplicación&quot;">​</a></h3><p>Para restablecer todos los ajustes a sus valores predeterminados:</p><ol><li>Cierra Nicasa</li><li>Elimina la carpeta de datos de la aplicación</li><li>Reinicia Nicasa</li></ol><h3 id="opciones-de-linea-de-comandos" tabindex="-1">Opciones de línea de comandos <a class="header-anchor" href="#opciones-de-linea-de-comandos" aria-label="Permalink to &quot;Opciones de línea de comandos&quot;">​</a></h3><p>Para usuarios avanzados, Nicasa admite argumentos de línea de comandos:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nicasa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --verbose</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # Activa el registro detallado</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nicasa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reset-settings</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Restablece todos los ajustes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nicasa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/folder</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Abre una carpeta concreta</span></span></code></pre></div><h2 id="obtener-mas-ayuda" tabindex="-1">Obtener más ayuda <a class="header-anchor" href="#obtener-mas-ayuda" aria-label="Permalink to &quot;Obtener más ayuda&quot;">​</a></h2><p>Si estas soluciones no resuelven tu problema:</p><ol><li>Consulta nuestras <a href="/es/guide/faq.html">preguntas frecuentes</a></li><li>Busca en las <a href="https://github.com/nicasa-project/nicasa-support/issues" target="_blank" rel="noreferrer">incidencias</a> existentes</li><li>Crea una nueva incidencia con: <ul><li>Tu sistema operativo y versión</li><li>La versión de Nicasa</li><li>Los pasos para reproducir el problema</li><li>Cualquier mensaje de error o captura de pantalla</li></ul></li></ol>`,68)])])}const h=e(l,[["render",n]]);export{m as __pageData,h as default};
